#!/usr/bin/env python3
"""Topic-specific enrichment metadata for the Spark curriculum.

Each entry is keyed by the notebook path relative to ``notebooks/``. The
enrichment script inserts the content into the existing notebook without
deleting the learner's cells.

The text is deliberately specific to the topic. Avoid generic "Spark is used
in e-commerce" paragraphs; explain the mechanism, the business problem, and
the trade-off.
"""


def uc(title, industry, scenario, problem, why, implementation, result, alternative, tradeoffs):
    """Build one real-world use-case record."""
    return {
        "title": title,
        "industry": industry,
        "scenario": scenario,
        "problem": problem,
        "why": why,
        "implementation": implementation,
        "result": result,
        "alternative": alternative,
        "tradeoffs": tradeoffs,
    }


def topic(
    priority,
    effort,
    prereqs,
    depth,
    roles,
    problem,
    concepts,
    internals,
    use_cases,
    business,
    production,
    tradeoffs,
    experiment,
    debug,
    interview,
    next_step,
):
    """Build one topic enrichment record."""
    return {
        "priority": priority,
        "effort": effort,
        "prereqs": prereqs,
        "depth": depth,
        "roles": roles,
        "problem": problem,
        "concepts": concepts,
        "internals": internals,
        "use_cases": use_cases,
        "business": business,
        "production": production,
        "tradeoffs": tradeoffs,
        "experiment": experiment,
        "debug": debug,
        "interview": interview,
        "next_step": next_step,
    }


TOPICS = {}

